# strict reconstruction based on exact square and L tiling, mapping missing quadrant offsets to color from demos seems output color = 2,3,4 based on missing-cell offset position? Samples map missing offsets:
# miss (bottom-left)->3 always; miss (top-right)->4 always; miss(top-left)->2 or 3 (d1 tile (2,1) actually missing bottom-right! Let's list offsets precisely output mapping observed.
# from placements:
# TL top-left (0,0) ->2 (D2), TL top-left (2,2)->2 (D3) [missing top-left]
# TL top-right (0,1)->4 (D1 at 1,4; D3 at0,2) [missing top-right]
# BL bottom-left (1,0)->3 (D1 tile1,0; D2 4,2; D3 2,0)
# BR bottom-right (1,1)->2 (D1 tile2,1) only.
# Squares all1.

grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
# exact tile extraction/cover
pts={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
tiles=[]
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if box<=pts:tiles.append((box,'sq',(r,c),None))
  for mr,mc in [(0,0),(0,1),(1,0),(1,1)]:
   t=box-{(r+mr,c+mc)}
   if t<=pts:tiles.append((t,'L',(r,c),(mr,mc)))
solutions=[]
def rec(rem,placements):
 if not rem: solutions.append(placements); return
 x=min(rem)
 for t,kind,loc,miss in tiles:
  if x in t and t<=rem:rec(rem-t,placements+[(t,kind,loc,miss)])
rec(pts,[])
print('solutions',len(solutions), 'tile types',[(k,loc,m) for _,k,loc,m in solutions[0]])
out=[[0]*7 for _ in range(7)]
for t,kind,(r,c),miss in solutions[0]:
 color=1 if kind=='sq' else {(0,0):2,(0,1):4,(1,0):3,(1,1):2}[miss]
 for x,y in t:out[x][y]=color
print(*out,sep='\n')
